u: -1, 1, 8
v: 0, 6.28318531, 40
//MESH_END

// D = number of lines per family, an INTEGER: the slider snaps to the integer on
// release. The := directive is read ONLY from the scriptCode.
D := int(1,20);

float N = clamp(floor(D + 0.5), 1.0, 20.0);

// The mesh sections are static text: there are always 20. The copies beyond N
// collapse into a point instead of being drawn.
float live = step(mesh, N - 0.5);

// FAMILY: E < 0.5 -> only sheet=+1. E >= 0.5 -> the two families alternated
// (even meshes sheet=+1, odd meshes sheet=-1), which DO MEET: it is the mesh of the
// double ruling. With two families the lines per family are N/2.
float both = step(0.5, E);
float sheet = mix(1.0, 1.0 - 2.0 * mod(mesh, 2.0), both);

// Index of the line WITHIN its own family, and how many there are.
float idx = mix(mesh, floor(mesh * 0.5), both);
float cnt = mix(N, ceil(N * 0.5), both);

float a = 6.28318531 * idx / cnt;

// L along the line: u in [-1,1] rescaled by B (half height of the segment).
float L = B * u;

// Punto sulla retta e frame costante (forma chiusa).
float ca = cos(a);
float sa = sin(a);
float k = 0.70710678;   // 1/sqrt(2)

float px = (A * ca - sheet * L * sa) * live;
float py = (A * sa + sheet * L * ca) * live;
float pz = (L) * live;

// n1 = (cos a, sin a, 0);  n2 = (-sin a, cos a, -sheet)/sqrt(2)
float cv = cos(v);
float sv = sin(v);

float nx = cv * ca + sv * (-sa * k);
float ny = cv * sa + sv * ( ca * k);
float nz =           sv * (-sheet  * k);

// The body becomes the body of vec4 getRawPosition(...): the return MUST be a
// vec4, with the fourth component (4D coordinate) at 0 for a surface in R^3.
return vec4(
    px + C * nx * live,
    py + C * ny * live,
    pz + C * nz * live,
    0.0
);
